/**
 * CHARACTERS — the human cast, Pip the cat, and Mote the Echo companion.
 *
 * Humans are entirely generated by `lib/humanoid.ts`: this file only decides
 * *who* each person is (build, garment, hair, colours, posture) and which poses
 * they need. That split is deliberate — an NPC's identity should be a dozen
 * lines of casting, never a dozen lines of pixel pushing.
 *
 * Casting rules used here:
 *   - Silhouette before colour. Cover the palette and Sera (long coat), Mira
 *     (apron + bun), Oren (slim + cap), Tavi (tall + wide stance), Nia (long
 *     hair, arms in), Elia (stout + wide hat) must still be distinguishable.
 *   - Every villager differs from every other villager in at least three of
 *     {build, height, hair style, outfit, palette}.
 *   - Hue is a character trait: Sera teal-grey, Mira warm red, Oren olive,
 *     Tavi orange, Nia blue, Elia plum, player green. Villagers take the six
 *     appended CLOTH_* ramps so they never poach a named character's colour.
 *
 * Pip and Mote are hand-drawn — a cat and a ball of light are not humanoids —
 * but they use the same mask/paint shading helpers, so they light identically.
 *
 * The runtime plays 'e' with flipX for west; no '_w' frames are generated.
 */
import { ArtBuild } from '../lib/registry.js';
import {
  charStrip, POSE_FPS, POSE_ONCE, mask, paint, limb, shift,
  type CharSpec, type Dir, type Pose,
} from '../lib/humanoid.js';
import { Surface } from '../lib/pixel.js';
import * as P from '../lib/palette.js';

const DIRS: Dir[] = ['s', 'n', 'e'];

function registerHuman(b: ArtBuild, who: string, spec: CharSpec, poses: Pose[]): void {
  for (const pose of poses) {
    for (const dir of DIRS) {
      b.addStrip(`char/${who}/${pose}_${dir}`, charStrip(spec, dir, pose), {
        key: `${who}_${pose}_${dir}`,
        frameRate: POSE_FPS[pose],
        repeat: POSE_ONCE[pose] ? 0 : -1,
      });
    }
  }
}

/** The pose set every speaking character needs (plan.md §55). */
const SPEAKING: Pose[] = ['idle', 'walk', 'talk', 'surprised', 'happy'];
/** Background townsfolk: enough to keep a street alive. */
const EXTRA: Pose[] = ['idle', 'walk', 'talk'];

